-- Curated, nonrepeating teaching cases: 12 original + 50 distinct previous core stories + 38 new stories.
-- Retire 438 repetitive variants without touching cases with existing student assignments.
create table if not exists public.retired_event_cases(
 game_id uuid not null,case_key text not null,snapshot jsonb not null,archived_at timestamptz not null default now(),
 primary key(game_id,case_key)
);
revoke all on public.retired_event_cases from anon,authenticated;
create or replace function private.seed_curated_event_bank(p_game uuid)
returns integer language plpgsql security definer set search_path=public,private,pg_temp as $$
declare result integer;
begin
 perform private.seed_event_bank_extended(p_game);
 insert into public.retired_event_cases(game_id,case_key,snapshot)
 select c.game_id,c.case_key,to_jsonb(c) from public.event_cases c
 where c.game_id=p_game and c.case_key ~ '^bank-expanded-(serious|light)-[0-9]+-(0[2-9]|10)$'
 on conflict do nothing;
 update public.event_cases c set status='archived'
 where c.game_id=p_game and c.case_key ~ '^bank-expanded-(serious|light)-[0-9]+-(0[2-9]|10)$';
 -- Assigned historical cases are retained in the archive for audit; never delete an assignment.
 delete from public.event_cases c
 where c.game_id=p_game and c.case_key ~ '^bank-expanded-(serious|light)-[0-9]+-(0[2-9]|10)$'
 and not exists(select 1 from public.event_assignments a where a.case_id=c.id);
 update public.event_cases c set
  title=split_part(c.title,': ',1),
  situation=split_part(replace(replace(c.situation,E'\\n\\n',E'\n\n'),E'\\n',E'\n'),E'\n\n',1),
  decision_options=jsonb_build_array('Открытое решение по ситуации: '||split_part(c.title,': ',1),
   'Провести проверку и общественное обсуждение','Оставить проблему без ответа'),
  effect_plan=jsonb_build_object('options',jsonb_build_array(
   jsonb_build_object('key','option_1','trust',2,'description','Проверенное публичное решение с оформленной ответственностью'),
   jsonb_build_object('key','option_2','trust',0,'description','Дополнительная оценка до принятия решения'),
   jsonb_build_object('key','option_3','trust',-2,'description','Отказ от обоснованного реагирования')))
 where c.game_id=p_game and c.case_key ~ '^bank-expanded-(serious|light)-[0-9]+-01$';
 update public.event_cases c set
 decision_options=jsonb_build_array('Предложить открытое решение: '||c.title,
 'Запросить независимую проверку перед действием','Не реагировать на обращения'),
 effect_plan=jsonb_build_object('options',jsonb_build_array(
 jsonb_build_object('key','option_1','trust',2),jsonb_build_object('key','option_2','trust',0),
 jsonb_build_object('key','option_3','trust',-2)))
 where c.game_id=p_game and c.case_key like 'bank-%' and c.case_key not like 'bank-expanded-%'
 and c.case_key not like 'bank-curated-%';
 insert into public.event_cases(game_id,case_key,title,situation,category,seriousness,audience,
  allowed_roles,verified,status,source_note,decision_options,effect_plan)
 select p_game,'bank-curated-'||v.kind||'-'||lpad(v.seq::text,2,'0'),
 v.title,v.situation,v.category,v.kind,
 case when v.kind='serious' and v.seq<=3 then 'all' else 'single' end,
 array[]::text[],false,'ready','Оригинальный вымышленный учебный кейс с тремя авторскими вариантами решения.',
 jsonb_build_array(v.positive,v.neutral,v.negative),
 jsonb_build_object('options',jsonb_build_array(
  jsonb_build_object('key','option_1','trust',2,'note','Обоснованное решение с проверкой процедур'),
  jsonb_build_object('key','option_2','trust',0,'note','Сбор информации до принятия решения'),
  jsonb_build_object('key','option_3','trust',-2,'note','Необоснованное либо потенциально неправомерное решение')
 )) from (values
('serious',1,'Кибератака на реестр','В понедельник утром сотрудники не смогли открыть реестр обращений граждан. Неизвестные потребовали выкуп, а резервная копия оказалась трёхдневной. Пока специалисты исследуют атаку, сотни заявителей не знают судьбу своих документов.','Цифровая инфраструктура','Изолировать систему, восстановить копию и уведомить заявителей','Перевести приём на бумагу до независимой проверки','Заплатить выкуп и скрыть происшествие'),
('serious',2,'Оползень под улицей','После ливней геологи нашли движение грунта под кварталом. Переселение нужно начинать до заключительной экспертизы, но свободного жилья недостаточно. Городской совет должен определить безопасную очередность помощи.','Безопасность','Немедленно расселить наиболее опасные дома с прозрачными критериями','Сначала поставить датчики и подготовить резервное жильё','Оставить жителей на месте ради экономии и не публиковать данные'),
('serious',3,'Пандусы в больнице','Пациент на инвалидной коляске не смог попасть на приём из-за сломанного подъёмника. Больница предлагает временную помощь волонтёров, общество требует системного решения.','Социальная политика','Отремонтировать подъёмник и проверить доступность всех входов','Создать временный доступ с согласованным графиком ремонта','Заменить очные приёмы дистанционными только для маломобильных граждан'),
('serious',4,'Приют после домашнего насилия','В городе не хватает мест для людей, ищущих срочную защиту от домашнего насилия. Ведомства спорят о финансировании временного жилья и конфиденциальности адресов.','Социальная политика','Открыть защищённые места и согласовать сопровождение с профильными службами','Использовать временные места и провести независимую оценку спроса','Публиковать адреса обратившихся и отказать в финансировании'),
('serious',5,'Ветеринарная эпидемия','На трёх фермах выявили заразную болезнь животных. Ветеринары предлагают карантин, фермеры требуют компенсации и прозрачных результатов лаборатории.','Сельское хозяйство','Ввести обоснованный карантин с компенсацией и открытым контролем','Провести повторную диагностику при временных ограничениях перемещения','Скрыть диагноз ради продаж и отменить ветеринарный контроль'),
('serious',6,'Электросеть в мороз','При морозе отключилась высоковольтная подстанция, обеспечивающая часть города. Больница перешла на резерв, но его хватит на ограниченное время. Энергетики предлагают последовательное восстановление кварталов.','Инфраструктура','Отдать приоритет больнице и системам жизнеобеспечения, сообщить график','Ввести временный режим энергосбережения и распределённые генераторы','Подключить коммерческие здания прежде больницы за дополнительную плату'),
('serious',7,'Архив под угрозой','После затопления городского архива намокли уникальные документы. Строители требуют немедленного доступа к помещению, реставраторы опасаются необратимой утраты коллекции.','Культура и протокол','Согласовать аварийную стабилизацию фонда и реставрацию со специалистами','Временно переместить сохранившиеся материалы в сухое хранилище','Уничтожить повреждённые документы без описи ради экономии'),
('serious',8,'Рыба у дамбы','После строительства небольшой дамбы в реке резко сократилось число нерестящихся рыб. Производитель электроэнергии предупреждает о потерях при изменении режима работы.','Экология','Ввести экологический пропуск воды и независимый мониторинг','Организовать сезонное регулирование с публичными данными','Игнорировать измерения и разрешить дальнейшее перекрытие русла'),
('serious',9,'Подозрение на картель','Три поставщика школьной формы предложили практически одинаковые цены, а один документ содержит ошибку конкурента. Антимонопольная служба запросила материалы закупки.','Экономика','Передать документы на проверку и обеспечить новую прозрачную закупку','Приостановить контракт до заключения антимонопольного органа','Заключить контракт с заранее выбранным поставщиком без расследования'),
('serious',10,'Пропавший спортивный грант','Молодёжная спортивная школа не получила обещанные средства, хотя в отчёте грант обозначен как использованный. Администраторы дают противоречивые объяснения.','Государственное управление','Провести проверку платежей и опубликовать проверенный отчёт','Заморозить оставшиеся перечисления до аудита','Списать недостачу без проверки и удалить запись об обещании'),
('serious',11,'Совет школьников','Школьники требуют включить представителя в совет по обновлению образовательной программы. Администрация опасается затягивания заседаний.','Образование','Ввести представительство с понятными полномочиями и процедурой обратной связи','Провести консультативные встречи перед изменением положения','Отказать в рассмотрении и закрыть канал для обращений учащихся'),
('serious',12,'Международная гуманитарная помощь','Соседняя страна попросила направить мобильные госпитали после землетрясения. Свой регион одновременно испытывает нехватку специалистов и техники.','Международные отношения','Предоставить ограниченную помощь после оценки внутренних резервов','Согласовать поставки медикаментов и обмен специалистами дистанционно','Обещать всю технику без учёта безопасности местных пациентов'),
('serious',13,'Временное размещение семей','После крупного пожара в соседнем регионе прибыли семьи без документов и жилья. Волонтёры помогают, но местные службы не согласовали доступ к школам и медицине.','Социальная политика','Организовать временное жильё и равный доступ к неотложным услугам','Создать межведомственный пункт регистрации и временную поддержку','Отказать всем прибывшим в помощи без индивидуального рассмотрения'),
('serious',14,'Карьер у заповедника','Компания предложила добывать минералы вблизи заповедной территории и обещает сотни рабочих мест. Экологи предупреждают о рисках для грунтовых вод.','Экология','Потребовать независимую экологическую оценку и публичные слушания','Изучить альтернативную площадку и условия компенсаций','Разрешить добычу без экспертизы и скрыть природоохранные ограничения'),
('serious',15,'Инициатива о местном референдуме','Жители собрали подписи за обсуждение транспортной реформы на местном референдуме. Избирательная комиссия указывает на спор о допустимости формулировки вопроса.','Муниципальное управление','Проверить законность вопроса и обеспечить прозрачную процедуру инициативы','Предложить публичные слушания параллельно правовой проверке','Отклонить все подписи без проверки и без мотивированного решения'),
('serious',16,'Дроны лесной охраны','Лесное ведомство предлагает использовать беспилотники для раннего выявления пожаров. Жители опасаются съёмки частных участков и отсутствия понятных правил хранения видео.','Безопасность','Утвердить ограниченные маршруты, сроки хранения и общественный контроль','Запустить малый пилот с независимой оценкой приватности','Разрешить круглосуточную съёмку частных домов без уведомлений'),
('serious',17,'Школа и местные языки','Сельские родители просят организовать факультатив по родному языку. Преподавателей мало, но университет готов вести смешанный формат.','Образование','Поддержать добровольный факультатив с доступом для всех желающих','Начать с дистанционной пилотной программы и оценки спроса','Запретить инициативу без обсуждения и убрать обращения из протокола'),
('serious',18,'Скорая помощь в распутицу','Весной грунтовую дорогу к деревне размыло. Машина скорой помощи не может проехать, а ближайшая больница находится далеко.','Здравоохранение','Организовать временный медицинский пункт и проезд для экстренных служб','Согласовать резервный маршрут и целевое укрепление дороги','Отказаться принимать вызовы из деревни до лета'),
('serious',19,'Аренда для молодых специалистов','Резкий рост арендных ставок мешает привлечь учителей и врачей в районный центр. Часть собственников готова участвовать в социальной программе.','Социальная политика','Запустить прозрачную программу субсидированной аренды по нуждаемости','Сначала исследовать рынок и предложить налоговые стимулы собственникам','Предоставить бюджетное жильё только родственникам членов комиссии'),
('serious',20,'Фейковая эвакуация','Поддельное сообщение якобы от администрации требует немедленно покинуть город из-за аварии на водопроводе. Официальные службы аварии не подтверждают.','Цифровая инфраструктура','Оперативно опровергнуть сообщение, дать проверяемые каналы и уведомить жителей','Опубликовать совместное сообщение после дополнительной проверки','Удалить достоверные обращения и угрожать жителям без разъяснений'),
('serious',21,'Пляж без спасателей','Во время жары на городском пляже резко вырос поток отдыхающих. Спасательная станция работает с недокомплектом, а закрытие пляжа вызовет протесты.','Безопасность','Ограничить опасные зоны и оперативно привлечь подготовленных спасателей','Изменить часы посещения до укомплектования станции','Оставить пляж без спасателей и скрыть предупреждения'),
('serious',22,'Экзаменационная утечка','За день до экзамена в сети появился файл, похожий на закрытые задания. Студенты опасаются пересдачи, администрация не установила источник.','Образование','Провести независимую проверку и подготовить равные условия для всех','Назначить резервный комплект только после установления подлинности','Обвинить случайных студентов без доказательств и раскрыть их данные'),
('serious',23,'Поставка инсулина','Аптеки нескольких районов сообщают о задержке поставок жизненно важного препарата. Соседний регион предлагает временную передачу запасов.','Здравоохранение','Организовать перераспределение под медицинским контролем и восстановить закупки','Ввести оперативный реестр потребности и временные маршруты доставки','Скрыть дефицит и продолжать отказывать пациентам без альтернатив'),
('serious',24,'Археологическая находка','При прокладке дороги строители нашли следы древнего поселения. Остановка работ грозит штрафом, но археологи считают находку потенциально значимой.','Культура и протокол','Приостановить участок и провести охранную археологическую экспертизу','Изменить участок трассы после экспресс-исследования','Уничтожить предметы и продолжить работы без уведомления специалистов'),
('light',1,'Талисман-аксолотль','Детский совет предложил сделать талисманом центра науки аксолотля в очках. Дизайн понравился школьникам, но у чиновников нет единого мнения.','Культура и протокол','Провести открытый конкурс вариантов талисмана','Использовать рисунок в пробной выставке и собрать отзывы','Запретить обсуждение только потому, что персонаж слишком смешной'),
('light',2,'Музей бюрократии','Студенты собрали экспонаты для временного музея нелепых справок, устаревших печатей и ненужных очередей. Администрация опасается насмешек.','Культура и протокол','Поддержать выставку и добавить стенд об отменённых процедурах','Выделить пространство для однодневного формата','Изъять выставку без объяснения причин'),
('light',3,'Парк для собак','Владельцы собак предлагают огороженную площадку, а соседняя школа просит оставить территорию для спортивных мероприятий.','Муниципальное управление','Согласовать зонирование и график совместного использования','Провести открытый опрос жителей о двух доступных участках','Передать всё место частному клубу без консультаций'),
('light',4,'Поэзия на остановках','Городской транспорт предложил записывать короткие стихи вместо обычных объявлений на некоторых остановках. Пассажиры спорят об удобстве.','Культура и протокол','Запустить добровольный поэтический маршрут без замены служебных объявлений','Провести пилот на одном маршруте и собрать отзывы','Убрать объявления об остановках ради развлечения'),
('light',5,'Самая длинная скамейка','Дизайнеры предложили создать на площади непрерывную извилистую скамью. Дети в восторге, а коммунальщики предупреждают о дорогой уборке.','Муниципальное управление','Установить разборный прототип и проверить расходы на содержание','Организовать конкурс компактных вариантов и выбрать по критериям','Закупить самый дорогой проект без сметы'),
('light',6,'Настолка для чиновников','Молодёжный совет выпустил настольную игру, где игрокам приходится объяснять вымышленные муниципальные решения. Депутаты неожиданно спорят о правилах.','Образование','Провести публичную игровую сессию и собрать идеи об улучшении процедур','Начать с одной пилотной группы','Обязать все школы купить игру у одного знакомого автора'),
('light',7,'Гриб-рекордсмен','На городской лужайке вырос огромный гриб, и жители предлагают создать вокруг него экскурсионный маршрут. Биологи просят не нарушать природную среду.','Экология','Организовать безопасное наблюдение с советами биологов','Разместить информационную табличку без расширения доступа','Сорвать гриб ради фотографии для отчёта'),
('light',8,'Фестиваль потерянных стульев','На складе дома культуры нашли десятки разных стульев от прежних мероприятий. Художники предлагают устроить из них уличную инсталляцию.','Культура и протокол','Создать временную выставку с проверкой безопасности конструкций','Передать часть мебели в мастерскую для ремонта','Выставить неисправные стулья без проверки креплений'),
('light',9,'Очередь как спектакль','Актёры предложили сыграть сатиру про бесконечные очереди прямо в холле ведомства. Посетители смеются, а сотрудники переживают за работу учреждения.','Государственное управление','Провести спектакль после приёма и собрать предложения по сервису','Организовать выступление в отдельном зале','Провести его во время приёма с блокировкой входа'),
('light',10,'Печать наоборот','На тираж городских сувениров нанесли герб вверх ногами. Производитель предлагает забрать весь тираж, а художники считают его коллекционным.','Культура и протокол','Исправить официальные изделия, а бракованные продать как неофициальные сувениры','Провести опрос о допустимости творческой версии сувенира','Выдать ошибочные сувениры за официальный стандарт'),
('light',11,'Театр на остановке','Независимая театральная труппа хочет показывать короткие пьесы на остановках в непиковые часы. Перевозчики боятся толпы у проезжей части.','Культура и протокол','Предложить безопасные места и согласованный график выступлений','Провести представление в ближайшем парке как пилот','Разрешить сцены на проезжей части без ограждений'),
('light',12,'Соседский хор','Жители многоэтажного дома организовали хор во дворе. Репетиции радуют одних соседей, но мешают семьям с маленькими детьми.','Социальная политика','Согласовать дневные часы и альтернативную площадку','Организовать разовое выступление в доме культуры','Объявить обязательные репетиции по ночам'),
('light',13,'Цвет нового моста','Архитекторы предложили три цвета нового пешеходного мостика, а горожане начали публиковать мемы с фантастическими вариантами.','Муниципальное управление','Провести открытое голосование с учётом требований безопасности','Выбрать нейтральный вариант после консультации с архитекторами','Заменить светоотражающую маркировку на тёмную краску без проверки'),
('light',14,'Капсула времени','В день города школьники предлагают заложить капсулу времени с письмами себе через двадцать лет. Никто не определил, кто отвечает за хранение.','Образование','Передать капсулу музею с документированием срока вскрытия','Создать цифровой архив писем по добровольному согласию','Собрать личные письма детей и опубликовать без разрешения')
 ) as v(kind,seq,title,situation,category,positive,neutral,negative)
 on conflict(game_id,case_key) do update set
 title=excluded.title,situation=excluded.situation,category=excluded.category,
 seriousness=excluded.seriousness,audience=excluded.audience,decision_options=excluded.decision_options,
 effect_plan=excluded.effect_plan;
 select count(*) into result from public.event_cases where game_id=p_game and status='ready'
  and case_key like 'bank-%';
 return result;
end;
$$;
revoke all on function private.seed_curated_event_bank(uuid) from public,anon,authenticated;
create or replace function public.seed_game_event_bank(p_game_id uuid)
returns integer language plpgsql security definer set search_path=public,private,pg_temp as $$
begin
 if not private.is_game_teacher(p_game_id) then raise exception 'Teacher access required';end if;
 return private.seed_curated_event_bank(p_game_id);
end;
$$;
create or replace function private.seed_bank_when_teacher_joins()
returns trigger language plpgsql security definer set search_path=public,private,pg_temp as $$
begin
 if new.kind='teacher' then perform private.seed_curated_event_bank(new.game_id);end if;
 return new;
end;
$$;
do $$declare g record;begin for g in select id from public.games loop
 perform private.seed_curated_event_bank(g.id);
end loop;end$$;